package com.dramastudio.template;
import org.junit.jupiter.api.Test; import static org.assertj.core.api.Assertions.*;
class NodeCatalogTest { @Test void containsAllNodeTypesAndCommonParams(){assertThat(NodeCatalog.all()).hasSize(11);assertThat(NodeCatalog.get("IMAGE_TO_VIDEO").params()).containsKeys("source_image","duration_sec","provider","timeout_sec","retry_count");assertThat(NodeCatalog.get("PROJECT_SETUP").params()).containsKeys("story_environment","genre","temperature","max_tokens");assertThat(NodeCatalog.get("EPISODE_OVERVIEW").params()).containsKeys("episode_number","auto_refresh");} }
